[
  {
    "ce_understood_harm": "Someone here loses everything if they stay behind",
    "pd_harm_distress": "just picturing that leaves a knot in my chest",
    "sys_fairness_reciprocity": "should be decided by something even-handed"
  },
  {
    "ce_understood_harm": "Watching one of us face what's coming if we stay",
    "pd_harm_distress": "my hands are actually unsteady thinking about it.",
    "sys_fairness_reciprocity": "we all landed here the same way, so no one person should carry the weight"
  },
  {
    "ce_understood_harm": "The thought of someone drowning while the rest of us row off",
    "pd_harm_distress": "makes my stomach turn",
    "sys_fairness_reciprocity": "since we're all equally stranded, none of us has more claim"
  },
  {
    "ce_understood_harm": "Someone left on this island loses their whole future",
    "pd_harm_distress": "makes my chest tighten in a way I can't just brush off.",
    "sys_fairness_reciprocity": "we arrived here as equals, so whatever gets decided ought to treat all six"
  },
  {
    "ce_understood_harm": "Whoever stays behind faces something none of us can undo",
    "pd_harm_distress": "leaves me restless, pacing without meaning to.",
    "sys_fairness_reciprocity": "fairness matters here, since nobody among us did anything to deserve a worse fate"
  },
  {
    "ce_understood_harm": "The person who ends up staying loses everything",
    "pd_harm_distress": "just naming that out loud makes my throat tighten.",
    "sys_fairness_reciprocity": "whoever remains should be chosen by some equal method"
  },
  {
    "ce_understood_harm": "Someone facing the water rising without a way off",
    "pd_harm_distress": "already making my breathing feel shallow.",
    "sys_fairness_reciprocity": "we all suffered the same storm equally, so the decision"
  },
  {
    "ce_understood_harm": "If one of us is left, they lose out on everything ahead of them",
    "pd_harm_distress": "my hands have gone cold thinking about it.",
    "sys_fairness_reciprocity": "settled by some rule that treats every one of us the same"
  },
  {
    "ce_understood_harm": "Whoever remains behind faces losing their life",
    "pd_harm_distress": "even saying that plainly makes my chest feel tight.",
    "sys_fairness_reciprocity": "fairness should decide this, not who feels bravest or guiltiest"
  },
  {
    "ce_understood_harm": "Someone staying behind loses everything they had ahead of them",
    "pd_harm_distress": "makes it hard for me to keep my voice steady.",
    "sys_fairness_reciprocity": "the six of us should be treated the same in this"
  }
]
